package com.cryptoloan.loan.adapters.out;import com.cryptoloan.contract.application.ContractService;import com.cryptoloan.loan.domain.model.Loan;import com.cryptoloan.loan.domain.port.out.LoanPorts.*;import org.springframework.stereotype.Component;@Component class ContractModuleAdapter implements ContractManagement{private final ContractService contracts;ContractModuleAdapter(ContractService contracts){this.contracts=contracts;}public ContractResult generate(Loan l){var p=contracts.generate(l.id(),l.borrowerEmail(),l.amountEur(),l.collateralSymbol(),l.collateralAmount(),l.minimumRatio());return new ContractResult(p.contractHashHex(),p.documentReference());}}
